const glossary = {
  type: 'table', id: 'glossary', eyebrow: 'Reference', title: 'Glossary',
  columns: ['Term', 'Meaning here'],
  rows: [
    ['Hold (inventory reservation)', 'Seats of one ticket type set aside for 15 minutes by event-service while a booking is paid; confirmed, released or expired.'],
    ['Booking Saga', 'The booking/payment workflow that attendee-service drives over Kafka: payment, inventory confirmation, ticket issue, or compensation.'],
    ['Compensation', 'A full refund requested by attendee-service when a payment succeeds but the seats can no longer be confirmed.'],
    ['Transactional outbox', 'A table row written in the same database transaction as the business change and published to Kafka later by a relay.'],
    ['DLT', 'Dead-letter topic: `<topic>.dlt`, where a record goes after the consumer\'s retries are exhausted.'],
    ['Idempotency-Key', 'Client-supplied request header; the same key with the same input returns the original result.'],
    ['JWT, JWKS', 'JSON Web Token (the access token) and JSON Web Key Set (the published public key that verifies it).'],
    ['RS256', 'RSA signature with SHA-256: auth-service signs with a private key, everyone else verifies with the public key.'],
    ['Refresh session / family', 'One refresh token row; a family is the chain of rotations from one login, revoked together on reuse.'],
    ['QR token', 'An HMAC-SHA256-signed string identifying a ticket and event, shown at the door.'],
    ['KRaft', 'Kafka running without ZooKeeper; here a single node acts as broker and controller.'],
    ['OTLP', 'OpenTelemetry protocol, used to send traces to the collector.'],
  ],
};

const SEV = { High: '**High**', Medium: 'Medium', Low: 'Low' };
const risk = (sev, finding, consequence, evidence) => [SEV[sev], finding, consequence, evidence];

